import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { resolve } from "node:path";
import test from "node:test";

const repositoryRoot = resolve(fileURLToPath(new URL("../..", import.meta.url)));
const npm = process.platform === "win32" ? "npm.cmd" : "npm";

const focusedDoctorLane = () => {
  const env = { ...process.env };
  delete env.NODE_TEST_CONTEXT;
  delete env.NODE_OPTIONS;

  const result = spawnSync(npm, ["test", "-w", "@aos/schema", "--", "doctor-contract"], {
    cwd: repositoryRoot,
    encoding: "utf8",
    env
  });
  assert.ifError(result.error);

  const output = `${result.stdout ?? ""}${result.stderr ?? ""}`;
  assert.equal(
    result.status,
    0,
    `focused doctor-contract lane failed:\n${output.slice(-4000)}`
  );
  return output;
};

test("focused schema doctor-contract lane has no moduleless-package warning", () => {
  const output = focusedDoctorLane();
  assert.doesNotMatch(
    output,
    /\[MODULE_TYPELESS_PACKAGE_JSON\]/,
    "the focused schema lane must not require Node to reparse its tests as ES modules"
  );
});
